with valid_transactions as (select * from transactions where merchant in ('Lazada', 'Grab', 'Starbucks') or account_id in (1, 32, 34)), Summary as (select quarter(txn_time) as txn_quarter, date_format(txn_time, 'yyyy-MM') as txn_month, round(avg(amount), 2) as avg_amount, count(case when txn_type = 'FEE' then 1 end) as fee_count from valid_transactions group by quarter(txn_time), date_format(txn_time, 'yyyy-MM')) select * from Summary order by fee_count, 3
